fn replace_text(
    entries: &mut [(Value, Value)],
    name: &str,
    expected: &str,
    replacement: &str,
) -> Result<()> {
    let field = entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .with_context(|| format!("historical descriptor requires {name}"))?;
    if field.1 != Value::Text(expected.to_owned()) {
        bail!("historical descriptor {name} source value drifted");
    }
    field.1 = Value::Text(replacement.to_owned());
    Ok(())
}

fn remove_fields(entries: &mut Vec<(Value, Value)>, names: &[&str]) -> Result<()> {
    for name in names {
        let before = entries.len();
        entries.retain(|(key, _)| key != &Value::Text((*name).to_owned()));
        if entries.len() + 1 != before {
            bail!("historical descriptor {name} removal is not exact");
        }
    }
    Ok(())
}

